11	fn get_pool() -> deadpool_postgres::Pool {
12	    let database_url = std::env::var("DATABASE_URL")
13	        .unwrap_or_else(|_| "postgres://localhost/ironclaw_test".to_string());
14	
15	    let config: tokio_postgres::Config = database_url.parse().expect("Invalid DATABASE_URL");
16	
17	    let mgr = deadpool_postgres::Manager::new(config, tokio_postgres::NoTls);
18	    deadpool_postgres::Pool::builder(mgr)
19	        .max_size(4)
20	        .build()
21	        .expect("Failed to create pool")
22	}
