24	/// Try to get a connection, returning None if Postgres is unreachable.
25	/// Tests call this to skip gracefully in CI where no database is available.
26	async fn try_connect(pool: &deadpool_postgres::Pool) -> Option<()> {
27	    match pool.get().await {
28	        Ok(_) => Some(()),
29	        Err(e) => {
30	            eprintln!("skipping: database unavailable ({e})");
31	            None
32	        }
33	    }
34	}
