36	async fn cleanup_user(pool: &deadpool_postgres::Pool, user_id: &str) {
37	    let conn = pool.get().await.expect("Failed to get connection");
38	    conn.execute(
39	        "DELETE FROM memory_documents WHERE user_id = $1",
40	        &[&user_id],
41	    )
42	    .await
43	    .ok();
44	}
