47	async fn test_workspace_write_and_read() {
48	    let pool = get_pool();
49	    if try_connect(&pool).await.is_none() {
50	        return;
51	    }
52	    let user_id = "test_write_read";
53	    cleanup_user(&pool, user_id).await;
54	
55	    let workspace = Workspace::new(user_id, pool.clone());
56	
57	    // Write a file
58	    let doc = workspace
59	        .write("README.md", "# Hello World\n\nThis is a test.")
60	        .await
61	        .expect("Failed to write");
